{"file_path":"octal.go","content":"package octal

import "fmt"

// ParseOctal converts an octal number represented as a string into its
// decimal equivalent. Invalid input (empty string, or containing any
// character outside the '0'-'7' range) results in a decimal value of 0
// and a non-nil error.
func ParseOctal(input string) (int64, error) {
	if len(input) == 0 {
		return 0, fmt.Errorf("invalid octal input: %q", input)
	}

	var result int64
	for _, r := range input {
		if r < '0' || r > '7' {
			return 0, fmt.Errorf("invalid octal digit: %q", r)
		}
		digit := int64(r - '0')
		result = result*8 + digit
	}

	return result, nil
}
"}

